module tb;
    reg ring;
    reg vibrate_mode;
    wire ringer;
    wire motor;

    TopModule dut (
        .ring(ring),
        .vibrate_mode(vibrate_mode),
        .ringer(ringer),
        .motor(motor)
    );

    initial begin
        // Test all 4 input combinations
        ring = 0; vibrate_mode = 0; #10;
        if (ringer !== 0 || motor !== 0) begin
            $display("SELFTEST FAIL: ring=0, vibrate=0 -> ringer=%b, motor=%b", ringer, motor);
            $finish;
        end

        ring = 0; vibrate_mode = 1; #10;
        if (ringer !== 0 || motor !== 0) begin
            $display("SELFTEST FAIL: ring=0, vibrate=1 -> ringer=%b, motor=%b", ringer, motor);
            $finish;
        end

        ring = 1; vibrate_mode = 0; #10;
        if (ringer !== 1 || motor !== 0) begin
            $display("SELFTEST FAIL: ring=1, vibrate=0 -> ringer=%b, motor=%b", ringer, motor);
            $finish;
        end

        ring = 1; vibrate_mode = 1; #10;
        if (ringer !== 0 || motor !== 1) begin
            $display("SELFTEST FAIL: ring=1, vibrate=1 -> ringer=%b, motor=%b", ringer, motor);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
